import{_ as o,a as i,a3 as a,o as t}from"./chunks/framework.edeurCMZ.js";const h=JSON.parse('{"title":"DFS FileAccess Audit Centralization","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/DFSAuditFileAccess.md","filePath":"devdoc/DFSAuditFileAccess.md","lastUpdated":1787329496000}'),c={name:"devdoc/DFSAuditFileAccess.md"};function l(s,e,d,n,r,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="dfs-fileaccess-audit-centralization" tabindex="-1">DFS FileAccess Audit Centralization <a class="header-anchor" href="#dfs-fileaccess-audit-centralization" aria-label="Permalink to &quot;DFS FileAccess Audit Centralization&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This page documents the DFS-owned FileAccess auditing model introduced for HPCC-35853.</p><p>The design goal is to move FileAccess emission responsibility into DFS so callers pass context and intent, while DFS decides:</p><ul><li>whether a call should emit an audit line,</li><li>which verb to emit,</li><li>what DFS-resolved enrichment fields to include.</li></ul><h2 id="record-format" tabindex="-1">Record format <a class="header-anchor" href="#record-format" aria-label="Permalink to &quot;Record format&quot;">​</a></h2><p>DFS emits a CSV-prefix plus logfmt-extras hybrid line:</p><p><code>,FileAccess,&lt;component&gt;,&lt;action&gt;[,&lt;logfmt extras&gt;]</code></p><p>The format is produced by <code>DFSAuditContext::buildFileAccessAuditLine()</code> and emitted by <code>DFSAuditContext::logFileAccess()</code>.</p><p>Current policy is to keep this format (no JSON migration in this change set).</p><h2 id="dfsauditcontext-contract" tabindex="-1">DFSAuditContext contract <a class="header-anchor" href="#dfsauditcontext-contract" aria-label="Permalink to &quot;DFSAuditContext contract&quot;">​</a></h2><p><code>DFSAuditContext</code> is a key/value context bag carried through DFS APIs.</p><p>Core methods:</p><ul><li><code>add()</code> returns a new context with extra key/value pairs</li><li><code>nested()</code> returns a copy marked nested</li><li><code>isNested()</code> reports whether nested suppression is active</li><li><code>setValue()</code> update keys</li><li><code>toLogfmt()</code> and <code>fromLogfmt()</code> serialize/deserialize wire context</li></ul><h3 id="process-defaults" tabindex="-1">Process defaults <a class="header-anchor" href="#process-defaults" aria-label="Permalink to &quot;Process defaults&quot;">​</a></h3><p><code>initDFSAudit()</code> installs default process context fields from config:</p><ul><li><code>component</code> (from component config tag)</li><li><code>instance</code> (from process name)</li></ul><p>Callers should still provide operation-scoped fields (user, wuid, lfn, etc).</p><h3 id="nested-suppression-protocol" tabindex="-1">Nested suppression protocol <a class="header-anchor" href="#nested-suppression-protocol" aria-label="Permalink to &quot;Nested suppression protocol&quot;">​</a></h3><p>Nested suppression prevents duplicate emits from inner DFS calls.</p><p>Rule:</p><ul><li>outer owner call uses normal context and may emit,</li><li>inner DFS calls receive <code>auditCtx.nested()</code> and must not emit.</li></ul><p>Every emit point must guard on:</p><p><code>if (!auditCtx.isNested()) { ... emit ... }</code></p><h2 id="accessmode-gating-and-verb-mapping" tabindex="-1">AccessMode gating and verb mapping <a class="header-anchor" href="#accessmode-gating-and-verb-mapping" aria-label="Permalink to &quot;AccessMode gating and verb mapping&quot;">​</a></h2><p>FileAccess emission is gated to content access, not metadata-only access.</p><p>Content gate:</p><p><code>AccessMode::none == (accessMode &amp; AccessMode::meta)</code></p><p>Verb mapping for lookup:</p><ul><li><code>READ</code> for content lookups</li><li><code>EXTEND</code> when <code>AccessMode::extend</code> bit is set (for append/extend intent)</li></ul><p>Metadata-only access modes (for example <code>readMeta</code>, <code>writeMeta</code>) do not emit READ/EXTEND.</p><h2 id="dfs-emission-owner-points" tabindex="-1">DFS emission owner points <a class="header-anchor" href="#dfs-emission-owner-points" aria-label="Permalink to &quot;DFS emission owner points&quot;">​</a></h2><p>Primary emit points in DFS:</p><ul><li><code>lookup(...)</code> emits <code>READ</code>/<code>EXTEND</code> for content access</li><li><code>attach(...)</code> emits <code>CREATED</code></li><li><code>detach(...)</code> / remove-entry path emits <code>DELETED</code></li><li>logical rename and renamePhysical paths emit <code>RENAMED</code></li></ul><h3 id="superfile-lookup-behavior" tabindex="-1">Superfile lookup behavior <a class="header-anchor" href="#superfile-lookup-behavior" aria-label="Permalink to &quot;Superfile lookup behavior&quot;">​</a></h3><p>For content reads, superfile lookup emits:</p><ul><li>one record for the superfile lookup,</li><li>one record per leaf subfile resolved.</li></ul><h2 id="enrichment-fields" tabindex="-1">Enrichment fields <a class="header-anchor" href="#enrichment-fields" aria-label="Permalink to &quot;Enrichment fields&quot;">​</a></h2><p>DFS enriches records with fields callers may not reliably know:</p><ul><li><code>lfn</code> (target logical file)</li><li><code>lfn2</code> (source logical file for rename-style operations)</li><li><code>cluster</code> when unambiguous</li><li><code>fileSize</code> and <code>diskSize</code> where available via metadata-only size paths</li></ul><p>Size fields use current vocabulary:</p><ul><li><code>fileSize</code></li><li><code>diskSize</code></li></ul><h2 id="remote-and-foreign-boundary-behavior" tabindex="-1">Remote and foreign boundary behavior <a class="header-anchor" href="#remote-and-foreign-boundary-behavior" aria-label="Permalink to &quot;Remote and foreign boundary behavior&quot;">​</a></h2><p>Current policy for remote/foreign content lookup is dual emission:</p><ul><li>local/client side may emit,</li><li>server/service side may emit.</li></ul><p>Records should remain distinguishable by <code>component</code> and context fields.</p><h2 id="migration-pattern-for-callers" tabindex="-1">Migration pattern for callers <a class="header-anchor" href="#migration-pattern-for-callers" aria-label="Permalink to &quot;Migration pattern for callers&quot;">​</a></h2><p>When migrating a caller component:</p><ol><li>Build a base <code>DFSAuditContext</code> once per request/job (component, user, wuid, peer, instance-specific data).</li><li>Add per-call fields (<code>lfn</code>, <code>lfn2</code>, <code>graph</code>, <code>cluster</code>, <code>jobid</code>, etc) via <code>add()</code> or <code>setValue*()</code>.</li><li>Pass the context into DFS API calls (<code>lookup</code>, <code>attach</code>, <code>detach</code>, <code>removeEntry</code>, <code>rename</code>, <code>renamePhysical</code>).</li><li>Remove direct <code>LOG(MCauditInfo, &quot;,FileAccess,...&quot;)</code> or equivalent caller-side emit.</li><li>Use <code>nested()</code> when the caller intentionally keeps ownership of an operation-level verb and must suppress inner DFS emits.</li></ol><h2 id="known-exceptions-and-operation-specific-notes" tabindex="-1">Known exceptions and operation-specific notes <a class="header-anchor" href="#known-exceptions-and-operation-specific-notes" aria-label="Permalink to &quot;Known exceptions and operation-specific notes&quot;">​</a></h2><p>Some operations do not map cleanly to simple DFS create/delete/rename/read owner points. In those cases, retain explicit operation-level policy and document it in code/PR notes.</p><p>Examples currently handled with explicit policy include:</p><ul><li>DFU operation verbs such as <code>MOVE</code> and <code>REPLICATE</code></li><li>COPYENSURE physical-attach path represented as <code>ATTACH</code></li></ul><h2 id="guidance-for-log-consumers" tabindex="-1">Guidance for log consumers <a class="header-anchor" href="#guidance-for-log-consumers" aria-label="Permalink to &quot;Guidance for log consumers&quot;">​</a></h2><p>Consumers should treat these records as the stable source of DFS file access events and parse:</p><ul><li>fixed CSV prefix fields (<code>FileAccess</code>, component, action),</li><li>remaining extras as logfmt key/value data.</li></ul><p>Consumers should not assume all optional fields exist on every line. Field presence depends on operation type and available DFS metadata.</p>',57)])])}const m=o(c,[["render",l]]);export{h as __pageData,m as default};
